import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { api, ApiError } from './api';

// Mock fetch globally
const originalFetch = global.fetch;

describe('API Service Integration Tests', () => {
  let fetchMock: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    // Create a fresh mock for each test
    fetchMock = vi.fn();
    global.fetch = fetchMock;
  });

  afterEach(() => {
    // Restore original fetch
    global.fetch = originalFetch;
    vi.clearAllMocks();
  });

  describe('Request Deduplication - Concurrent POST Requests', () => {
    it('should deduplicate concurrent identical POST requests to AI endpoints', async () => {
      // Setup: Mock successful response
      const mockResponse = { result: 'AI generated content' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      // Execute: Make 3 concurrent identical requests to /api/ai/generate
      const body = { prompt: 'hello world', model: 'gpt-4' };
      const promises = [
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ];

      const results = await Promise.all(promises);

      // Verify: Only one fetch call was made
      expect(fetchMock).toHaveBeenCalledTimes(1);

      // Verify: All results are identical
      expect(results[0]).toEqual(mockResponse);
      expect(results[1]).toEqual(mockResponse);
      expect(results[2]).toEqual(mockResponse);
      expect(results[0]).toBe(results[1]); // Same reference
    });

    it('should deduplicate concurrent identical POST requests to replicate endpoints', async () => {
      const mockResponse = { image_url: 'https://example.com/image.png' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { model: 'stability-ai/sdxl', prompt: 'a cat' };
      const promises = [
        api.post('/api/replicate/generate', body),
        api.post('/api/replicate/generate', body),
        api.post('/api/replicate/generate', body),
      ];

      const results = await Promise.all(promises);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(results[0]).toEqual(mockResponse);
      expect(results[1]).toEqual(mockResponse);
      expect(results[2]).toEqual(mockResponse);
    });

    it('should make separate requests for different request bodies', async () => {
      const mockResponse1 = { result: 'Response 1' };
      const mockResponse2 = { result: 'Response 2' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse1,
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse2,
        });

      const body1 = { prompt: 'hello' };
      const body2 = { prompt: 'world' };

      const [result1, result2] = await Promise.all([
        api.post('/api/ai/generate', body1),
        api.post('/api/ai/generate', body2),
      ]);

      // Verify: Two separate fetch calls were made
      expect(fetchMock).toHaveBeenCalledTimes(2);
      expect(result1).toEqual(mockResponse1);
      expect(result2).toEqual(mockResponse2);
    });

    it('should make separate requests for different endpoints', async () => {
      const mockResponse1 = { result: 'Response 1' };
      const mockResponse2 = { result: 'Response 2' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse1,
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse2,
        });

      const body = { prompt: 'hello' };

      const [result1, result2] = await Promise.all([
        api.post('/api/ai/generate', body),
        api.post('/api/ai/chat', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(2);
      expect(result1).toEqual(mockResponse1);
      expect(result2).toEqual(mockResponse2);
    });

    it('should execute new request after previous one completes', async () => {
      const mockResponse1 = { result: 'Response 1' };
      const mockResponse2 = { result: 'Response 2' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse1,
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => mockResponse2,
        });

      const body = { prompt: 'hello' };

      // First request
      const result1 = await api.post('/api/ai/generate', body);

      // Wait a bit to ensure cleanup
      await new Promise((resolve) => setTimeout(resolve, 10));

      // Second request (after first completes)
      const result2 = await api.post('/api/ai/generate', body);

      // Both requests should execute separately
      expect(fetchMock).toHaveBeenCalledTimes(2);
      expect(result1).toEqual(mockResponse1);
      expect(result2).toEqual(mockResponse2);
    });
  });

  describe('Deduplication Bypass Option', () => {
    it('should bypass deduplication when bypassDeduplication is true', async () => {
      const mockResponse = { result: 'AI response' };

      // Mock three separate responses
      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 2 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 3 }),
        });

      const body = { prompt: 'hello' };

      // Make three concurrent requests with bypass enabled
      const promises = [
        api.post('/api/ai/generate', body, { bypassDeduplication: true }),
        api.post('/api/ai/generate', body, { bypassDeduplication: true }),
        api.post('/api/ai/generate', body, { bypassDeduplication: true }),
      ];

      const results = await Promise.all(promises);

      // Verify: Three separate fetch calls were made
      expect(fetchMock).toHaveBeenCalledTimes(3);

      // Verify: Each result is different
      expect(results[0]).toEqual({ result: 'AI response', id: 1 });
      expect(results[1]).toEqual({ result: 'AI response', id: 2 });
      expect(results[2]).toEqual({ result: 'AI response', id: 3 });
    });

    it('should support bypass option with custom headers', async () => {
      const mockResponse = { result: 'Success' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { data: 'test' };
      const customHeaders = { 'X-Custom-Header': 'custom-value' };

      await api.post('/api/ai/generate', body, {
        bypassDeduplication: true,
        headers: customHeaders,
      });

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(fetchMock).toHaveBeenCalledWith(
        expect.any(String),
        expect.objectContaining({
          headers: expect.objectContaining({
            'X-Custom-Header': 'custom-value',
          }),
        })
      );
    });

    it('should deduplicate normally when bypassDeduplication is false', async () => {
      const mockResponse = { result: 'AI response' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { prompt: 'hello' };

      const promises = [
        api.post('/api/ai/generate', body, { bypassDeduplication: false }),
        api.post('/api/ai/generate', body, { bypassDeduplication: false }),
        api.post('/api/ai/generate', body, { bypassDeduplication: false }),
      ];

      await Promise.all(promises);

      // Should still deduplicate
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should work with GET requests and bypass option', async () => {
      const mockResponse = { profile: 'user data' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, timestamp: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, timestamp: 2 }),
        });

      const promises = [
        api.get('/api/user/profile', { bypassDeduplication: true }),
        api.get('/api/user/profile', { bypassDeduplication: true }),
      ];

      await Promise.all(promises);

      // Two separate calls with bypass
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });
  });

  describe('Endpoint Filtering - Deduplicate Only Configured Endpoints', () => {
    it('should deduplicate AI endpoints', async () => {
      const mockResponse = { result: 'AI result' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { prompt: 'test' };
      await Promise.all([
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate chat endpoints', async () => {
      const mockResponse = { messages: [] };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      await Promise.all([
        api.get('/api/chat/conversations'),
        api.get('/api/chat/conversations'),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate image endpoints', async () => {
      const mockResponse = { image_url: 'https://example.com/image.png' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { image_id: '123' };
      await Promise.all([
        api.post('/api/images/process', body),
        api.post('/api/images/process', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate user profile endpoints', async () => {
      const mockResponse = { name: 'John Doe' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      await Promise.all([
        api.get('/api/user/profile'),
        api.get('/api/user/profile'),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate user API key endpoints', async () => {
      const mockResponse = { keys: [] };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      await Promise.all([
        api.get('/api/user/api-keys'),
        api.get('/api/user/api-keys'),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should NOT deduplicate auth endpoints', async () => {
      const mockResponse = { token: 'abc123' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, session: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, session: 2 }),
        });

      const body = { email: 'test@example.com', password: 'password' };

      await Promise.all([
        api.post('/api/auth/login', body),
        api.post('/api/auth/login', body),
      ]);

      // Auth endpoints should NOT be deduplicated - expect 2 calls
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('should NOT deduplicate streaming endpoints', async () => {
      const mockResponse = { chunk: 'data' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 2 }),
        });

      const body = { prompt: 'test' };

      await Promise.all([
        api.post('/api/ai/stream', body),
        api.post('/api/ai/stream', body),
      ]);

      // Streaming endpoints should NOT be deduplicated
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('should NOT deduplicate last-login endpoint', async () => {
      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ timestamp: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ timestamp: 2 }),
        });

      await Promise.all([
        api.post('/api/user/last-login', {}),
        api.post('/api/user/last-login', {}),
      ]);

      // last-login should NOT be deduplicated (intentional action tracking)
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('should NOT deduplicate unknown/unconfigured endpoints', async () => {
      const mockResponse = { data: 'test' };

      fetchMock
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 1 }),
        })
        .mockResolvedValueOnce({
          ok: true,
          status: 200,
          json: async () => ({ ...mockResponse, id: 2 }),
        });

      const body = { data: 'test' };

      await Promise.all([
        api.post('/api/unknown/endpoint', body),
        api.post('/api/unknown/endpoint', body),
      ]);

      // Unknown endpoints should NOT be deduplicated (conservative default)
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });
  });

  describe('Error Propagation to Concurrent Callers', () => {
    it('should propagate network errors to all concurrent callers', async () => {
      const networkError = new Error('Network error');
      fetchMock.mockRejectedValueOnce(networkError);

      const body = { prompt: 'hello' };
      const promises = [
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ];

      // All promises should reject with the same error
      await expect(Promise.all(promises)).rejects.toThrow('Network error');

      // Only one fetch call should have been made
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should propagate API errors to all concurrent callers', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: false,
        status: 400,
        statusText: 'Bad Request',
        json: async () => ({ error: 'Invalid prompt' }),
      });

      const body = { prompt: '' };
      const promises = [
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ];

      // All promises should reject with ApiError
      try {
        await Promise.all(promises);
        expect.fail('Should have thrown an error');
      } catch (error) {
        expect(error).toBeInstanceOf(ApiError);
        expect((error as ApiError).message).toBe('Invalid prompt');
        expect((error as ApiError).status).toBe(400);
      }

      // Only one fetch call should have been made
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should propagate 401 errors to all concurrent callers', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: false,
        status: 401,
        statusText: 'Unauthorized',
        json: async () => ({ error: 'Authentication required' }),
      });

      const body = { prompt: 'test' };
      const promises = [
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ];

      try {
        await Promise.all(promises);
        expect.fail('Should have thrown an error');
      } catch (error) {
        expect(error).toBeInstanceOf(ApiError);
        expect((error as ApiError).status).toBe(401);
      }

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should propagate 500 errors to all concurrent callers', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: false,
        status: 500,
        statusText: 'Internal Server Error',
        text: async () => 'Server error occurred',
      });

      const body = { prompt: 'test' };
      const promises = [
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ];

      try {
        await Promise.all(promises);
        expect.fail('Should have thrown an error');
      } catch (error) {
        expect(error).toBeInstanceOf(ApiError);
        expect((error as ApiError).status).toBe(500);
      }

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should allow new request after previous request fails', async () => {
      // First request fails
      fetchMock.mockRejectedValueOnce(new Error('Network error'));

      const body = { prompt: 'test' };

      // First concurrent batch - all should fail
      try {
        await Promise.all([
          api.post('/api/ai/generate', body),
          api.post('/api/ai/generate', body),
        ]);
        expect.fail('Should have thrown an error');
      } catch (error) {
        expect((error as Error).message).toBe('Network error');
      }

      expect(fetchMock).toHaveBeenCalledTimes(1);

      // Wait for cleanup
      await new Promise((resolve) => setTimeout(resolve, 10));

      // Second request should execute (cache was cleared)
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ result: 'Success' }),
      });

      const result = await api.post('/api/ai/generate', body);

      expect(result).toEqual({ result: 'Success' });
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('should handle mixed concurrent success and failure scenarios', async () => {
      const mockResponse = { result: 'Success' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body1 = { prompt: 'success prompt' };
      const body2 = { prompt: 'fail prompt' };

      fetchMock.mockRejectedValueOnce(new Error('Network error'));

      const [result1] = await Promise.all([
        api.post('/api/ai/generate', body1),
        api.post('/api/ai/generate', body1), // Should share with first
      ]);

      // Second batch with different body - should fail
      try {
        await Promise.all([
          api.post('/api/ai/generate', body2),
          api.post('/api/ai/generate', body2),
        ]);
        expect.fail('Should have thrown an error');
      } catch (error) {
        expect((error as Error).message).toBe('Network error');
      }

      expect(result1).toEqual(mockResponse);
      expect(fetchMock).toHaveBeenCalledTimes(2); // One for each unique body
    });
  });

  describe('Single Network Call Verification', () => {
    it('should make only one network call for 10 concurrent identical requests', async () => {
      const mockResponse = { result: 'AI response' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { prompt: 'test' };
      const promises = Array.from({ length: 10 }, () =>
        api.post('/api/ai/generate', body)
      );

      const results = await Promise.all(promises);

      // Verify: Only one fetch call
      expect(fetchMock).toHaveBeenCalledTimes(1);

      // Verify: All results are identical
      results.forEach((result) => {
        expect(result).toEqual(mockResponse);
      });
    });

    it('should make only one network call for rapid concurrent GET requests', async () => {
      const mockResponse = { profile: 'user data' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const promises = Array.from({ length: 5 }, () =>
        api.get('/api/user/profile')
      );

      const results = await Promise.all(promises);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      results.forEach((result) => {
        expect(result).toEqual(mockResponse);
      });
    });

    it('should verify fetch was called with correct parameters', async () => {
      const mockResponse = { result: 'Success' };
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockResponse,
      });

      const body = { prompt: 'hello', model: 'gpt-4' };
      await Promise.all([
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(fetchMock).toHaveBeenCalledWith(
        expect.stringContaining('/api/ai/generate'),
        expect.objectContaining({
          method: 'POST',
          headers: expect.objectContaining({
            'Content-Type': 'application/json',
          }),
          body: JSON.stringify(body),
          credentials: 'include',
        })
      );
    });

    it('should handle empty response (204 status) correctly', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 204,
      });

      const body = { data: 'test' };
      const results = await Promise.all([
        api.post('/api/ai/process', body),
        api.post('/api/ai/process', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(results[0]).toEqual({});
      expect(results[1]).toEqual({});
    });
  });

  describe('API Methods - All HTTP Methods Support Deduplication', () => {
    it('should deduplicate GET requests', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ data: 'test' }),
      });

      await Promise.all([
        api.get('/api/user/profile'),
        api.get('/api/user/profile'),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate POST requests', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ data: 'test' }),
      });

      const body = { data: 'test' };
      await Promise.all([
        api.post('/api/ai/generate', body),
        api.post('/api/ai/generate', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate PATCH requests', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ data: 'updated' }),
      });

      const body = { name: 'John' };
      await Promise.all([
        api.patch('/api/user/profile', body),
        api.patch('/api/user/profile', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate PUT requests', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ data: 'replaced' }),
      });

      const body = { settings: { theme: 'dark' } };
      await Promise.all([
        api.put('/api/user/preferences', body),
        api.put('/api/user/preferences', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('should deduplicate DELETE requests', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => ({ deleted: true }),
      });

      const body = { id: '123' };
      await Promise.all([
        api.delete('/api/images/delete', body),
        api.delete('/api/images/delete', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
    });
  });

  describe('Type Safety and Response Handling', () => {
    it('should preserve type information for typed responses', async () => {
      interface UserProfile {
        id: string;
        name: string;
        email: string;
      }

      const mockProfile: UserProfile = {
        id: '123',
        name: 'John Doe',
        email: 'john@example.com',
      };

      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => mockProfile,
      });

      const results = await Promise.all([
        api.get<UserProfile>('/api/user/profile'),
        api.get<UserProfile>('/api/user/profile'),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(results[0]).toEqual(mockProfile);
      expect(results[1]).toEqual(mockProfile);

      // TypeScript compile-time check (not runtime)
      const name: string = results[0].name;
      expect(name).toBe('John Doe');
    });

    it('should handle non-JSON responses gracefully', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        status: 200,
        json: async () => {
          throw new Error('Not JSON');
        },
      });

      const body = { data: 'test' };
      const results = await Promise.all([
        api.post('/api/ai/process', body),
        api.post('/api/ai/process', body),
      ]);

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(results[0]).toEqual({});
      expect(results[1]).toEqual({});
    });
  });
});
